import React from "react";

export default function LudoBoard({ gameId, playerId, entryFee }) {
  return (
    <div className="ludo-board">
      <h2>Welcome to Ludo Game</h2>
      <p>Game ID: {gameId}</p>
      <p>Your Player ID: {playerId}</p>
      <p>Entry Fee: ৳ {entryFee}</p>

      {/* এখানে Ludo গেমের বোর্ড বা গ্রাফিক্স যুক্ত করতে হবে */}
      <div className="board">
        {/* Ludo board components go here */}
      </div>
    </div>
  );
}
